import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialize the position series with zeros
    positions = pd.Series(0, index=df.index)

    # Calculate the Stochastic %K(12)
    def stochastic_k(data, n=12):
        hh = data['high'].rolling(window=n).max()
        ll = data['low'].rolling(window=n).min()
        k = 100 * (data['close'] - ll) / (hh - ll)
        k[k.isnull()] = 50  # %K = 50 when HH equals LL
        return k

    # Calculate the Stochastic %K(12) for the current bar
    k_values = stochastic_k(df)

    # Apply the trading strategy
    for i in range(len(df)):
        if positions[i] == 0:
            if k_values[i] < 12:
                positions[i] = 1
        elif positions[i] == 1:
            if k_values[i] > 45:
                positions[i] = 0

    return positions

import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialize the position series with zeros
    positions = pd.Series(0, index=df.index)

    # Calculate SMA and STD for the last 20 bars
    m = df['close'].rolling(window=20).mean()
    s = df['close'].rolling(window=20).std()

    # Warm-up period: do nothing
    if m.isnull().any() or s.isnull().any():
        return positions

    # Calculate the threshold for going long
    threshold = m - 2 * s

    # Apply the strategy rules
    for i in range(len(df)):
        if positions[i] == 0:
            if df['close'].iloc[i] < threshold:
                positions[i] = 1
        elif positions[i] == 1:
            if df['close'].iloc[i] >= m - 1 * s:
                positions[i] = 0

    return positions

import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialize the position series with zeros
    positions = pd.Series(0, index=df.index)

    # Calculate the middle, upper, and lower bands
    middle = df['close'].rolling(window=18).mean()
    upper = middle + 2.5 * df['close'].rolling(window=18).std()
    lower = middle - 2.5 * df['close'].rolling(window=18).std()

    # Determine the position for each bar
    for i in range(len(df)):
        if i < 17:
            # Warm-up period, stay flat
            continue
        if df['close'].iloc[i] > upper.iloc[i]:
            positions.iloc[i] = 1  # Long
        elif df['close'].iloc[i] < lower.iloc[i]:
            positions.iloc[i] = -1  # Short
        elif df['close'].iloc[i] <= middle.iloc[i] and positions.iloc[i] == 1:
            positions.iloc[i] = 0  # Exit long
        elif df['close'].iloc[i] >= middle.iloc[i] and positions.iloc[i] == -1:
            positions.iloc[i] = 0  # Exit short

    return positions
